function _parseWorkflowRunJobs(raw) {
    var parsed = raw;
    if (typeof raw === 'string') {
        try { parsed = JSON.parse(raw); } catch (e) { return []; }
    }
    if (parsed && Array.isArray(parsed.jobs)) return parsed.jobs;
